class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # Initialize a list to store the maximum value at each index after applying the operation
        dp = [0] * n

        # Iterate through the array and fill the dp list
        for i in range(n):
            if k > 0:
                dp[i] = nums[i] | (dp[i-1] if i > 0 else 0)

            if i > 0 and dp[i] == dp[i-1]:
                k -= 1

        # Apply the remaining operations to the maximum value
        max_value = dp[n-1]
        for _ in range(k):
            max_value |= (max_value & -max_value)

        return max_value
